<?php declare(strict_types=1); $this->layout('layouts/default',['title'=>$title,'currentPage'=>'notifications']); ?>
<section class="studio-page"><header class="studio-page-heading"><div><p class="studio-eyebrow">VISÃO GERAL</p><h2>Notificações</h2><p>Eventos globais ou destinados ao usuário atual, com origem e ação contextual.</p></div><div class="studio-heading-actions"><span class="studio-badge"><?= (int)$unread ?> não lida(s)</span><?php if($unread):?><form method="post"><?= $this->csrf() ?><button name="action" value="read_all">Marcar todas como lidas</button></form><?php endif;?></div></header><div class="studio-notification-list"><?php if($records===[]):?><p class="studio-panel studio-empty">Nenhuma notificação.</p><?php endif;?><?php foreach($records as $record):?><article class="studio-panel <?= $record['read_at']?'':'is-unread' ?>"><div><small><?= $this->e($record['source_type']?:'Sistema') ?></small><h3><?= $this->e($record['title']) ?></h3><p><?= $this->e($record['message']) ?></p><small><?= $this->e($record['created_at']) ?></small></div><div class="studio-notification-actions"><?php $link=$record['action_url']?:$record['link']; $link=is_string($link)&&str_starts_with($link,'/')?$link:null; if($link):?><a href="<?= $this->e($link) ?>">Abrir</a><?php endif;?><form method="post"><?= $this->csrf() ?><input type="hidden" name="id" value="<?= (int)$record['id'] ?>"><button name="action" value="<?= $record['read_at']?'unread':'read' ?>"><?= $record['read_at']?'Marcar não lida':'Marcar como lida' ?></button><button class="studio-danger-button" name="action" value="delete" onclick="return confirm('Excluir esta notificação?')">Excluir</button></form></div></article><?php endforeach;?></div></section>
